package bw.co.knowvera;

import java.net.URI;
import java.time.Instant;
import java.util.List;

public record ErrorResponse(
    /**
     * RFC 9457: A URI reference that identifies the problem type.
     */
    URI type,

    /**
     * RFC 9457: A short, human-readable summary of the problem type.
     */
    String title,

    /**
     * RFC 9457: The HTTP status code generated by the origin server for this occurrence.
     */
    int status,

    /**
     * RFC 9457: A human-readable explanation specific to this occurrence of the problem.
     */
    String detail,

    /**
     * RFC 9457: A URI reference that identifies the specific occurrence of the problem.
     */
    String instance,

    // --- Extension Members (Allowed by RFC 9457 Section 3.2) ---

    Instant timestamp,
    List<String> errors
) {
    
}
